/**
 * Personal API tokens. Reads that cross a tenant boundary take `orgId`; the
 * unauthenticated authenticate path looks up by hash alone, the same way
 * invitation acceptance does. The raw secret never reaches this module.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface InsertApiToken {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

/** Usable means not revoked and not yet expired at `now` (expiry is inclusive). */
function usablePredicate(now: IsoTimestamp) {
  return and(isNull(apiTokens.revokedAt), gt(apiTokens.expiresAt, now));
}

/**
 * Inserts a token when the user is under `maxUsable` in this organization.
 * Returns `null` without writing when the allowance is already full, so a
 * rejected create leaves the table unchanged.
 */
export async function insertApiToken(
  input: InsertApiToken,
  maxUsable: number,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const existing = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, input.orgId),
          eq(apiTokens.userId, input.userId),
          usablePredicate(input.createdAt),
        ),
      )
      .get();

    if ((existing?.value ?? 0) >= maxUsable) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: input.orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        prefix: input.prefix,
        tokenHash: input.tokenHash,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: input.createdAt,
        updatedAt: input.createdAt,
      })
      .returning()
      .get();

    return row ? toApiToken(row) : null;
  });
}

export async function findById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/** Credential lookup. The hash is the key; the row carries its own org. */
export async function findByTokenHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Every token the user holds in the org, revoked and expired included, newest first. */
export async function listForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), sql`rowid desc`)
    .all();
  return rows.map(toApiToken);
}

/**
 * Sets `revokedAt` when the token is still live. An already-revoked row is
 * left untouched and reported as `null` so the caller can tell the two apart.
 */
export async function revokeToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Records a successful authentication. A revoked or expired row is not
 * touched — a failed check must leave `lastUsedAt` as it was.
 */
export async function markUsed(
  tokenId: string,
  at: IsoTimestamp,
): Promise<boolean> {
  const row = getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at, updatedAt: at })
    .where(
      and(
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, at),
      ),
    )
    .returning({ id: apiTokens.id })
    .get();
  return row !== undefined;
}

/** Stamp helper shared with the service so expiry math uses one clock read. */
export function timestamp(date: Date = new Date()): IsoTimestamp {
  return toIsoTimestamp(date);
}

/**
 * Personal API tokens for scripts and CI.
 *
 * The secret is minted here, returned once, and only its hash is persisted.
 * Creation and revocation are announced on the event bus; the audit log
 * records them from that side, the same way the other audited actions work.
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { PermissionDeniedError, assertCan } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";
import type { PermissionAction } from "@/types/permission";

/** A user may hold this many usable tokens in one organization. */
const MAX_USABLE_TOKENS = 5;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Bytes of entropy after the `tfk_` prefix. Matches the session token width. */
const SECRET_BYTES = 32;

const SECRET_PREFIX = "tfk_";

/** Display prefix stored on the row: the first 12 characters of the secret. */
const PREFIX_LENGTH = 12;

/**
 * Role gate that throws the codebase's permission-denied error.
 *
 * `hasRoleAtLeast` is the check the product rule names (a viewer stays a
 * viewer even under the staff bypass). `assertCan` is what produces
 * `PermissionDeniedError` for an ordinary member.
 */
function assertRoleAtLeast(
  actor: Actor,
  atLeast: Role,
  action: PermissionAction,
  orgId: OrgId,
): void {
  if (hasRoleAtLeast(actor.role, atLeast)) return;
  assertCan(actor, action, orgResource(orgId));
  throw new PermissionDeniedError(action, {
    allowed: false,
    action,
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertRoleAtLeast(actor, "member", "project:create", parsed.orgId);
  }

  const created = new Date();
  const createdAt = toIsoTimestamp(created);
  const token = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiToken(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(created.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt,
    },
    MAX_USABLE_TOKENS,
  );

  if (!apiToken) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS} usable API tokens in an organization`,
    );
  }

  await emit("api_token.created", {
    orgId: apiToken.orgId,
    actorId: actor.userId,
    occurredAt: apiToken.createdAt,
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);

  if (userId !== actor.userId) {
    assertRoleAtLeast(actor, "admin", "org:update", orgId);
  }

  return apiTokenRepo.listForUser(orgId, userId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (existing.userId !== actor.userId) {
    assertRoleAtLeast(actor, "admin", "org:update", orgId);
  }

  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.revokeToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );

  // Lost a race with another revoke: the row is already revoked and this
  // call must not append a second audit entry.
  if (!revoked) {
    return requireFound(
      await apiTokenRepo.findById(orgId, tokenId),
      "ApiToken",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    orgId,
    actorId: actor.userId,
    occurredAt: revoked.revokedAt ?? toIsoTimestamp(new Date()),
    tokenId: revoked.id,
    name: revoked.name,
  });

  return revoked;
}

/**
 * Resolves the actor a presented token stands for.
 *
 * `null` means the credential is not usable: unknown, revoked, expired
 * (exactly at `expiresAt`), the user is no longer an active member, or the
 * organization has been deleted. A failure leaves the row unchanged. A
 * success stamps `lastUsedAt`. A `read` token always acts as a viewer; a
 * `write` token acts as the member's role at this moment.
 */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  const apiToken = await apiTokenRepo.findByTokenHash(hashToken(token));
  if (!apiToken) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.revokedAt !== null) return null;
  if (apiToken.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (!org || isArchived(org)) return null;

  const member = await memberRepo.findMember(apiToken.orgId, apiToken.userId);
  if (!member || member.status !== "active") return null;

  const stamped = await apiTokenRepo.markUsed(apiToken.id, now);
  if (!stamped) return null;

  return {
    userId: apiToken.userId,
    orgId: apiToken.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Revokes every still-live token the user holds in this organization,
 * expired ones included. Tokens that were already revoked keep their original
 * `revokedAt` and are not audited again. Other organizations are not queried.
 */
export async function revokeTokensForRemovedMember(
  orgId: OrgId,
  userId: UserId,
  actorId: UserId | null,
): Promise<void> {
  const tokens = await apiTokenRepo.listForUser(orgId, userId);
  const now = toIsoTimestamp(new Date());

  for (const token of tokens) {
    if (token.revokedAt !== null) continue;

    const revoked = await apiTokenRepo.revokeToken(orgId, token.id, now);
    if (!revoked) continue;

    await emit("api_token.revoked", {
      orgId,
      actorId,
      occurredAt: revoked.revokedAt ?? now,
      tokenId: revoked.id,
      name: revoked.name,
    });
  }
}

/** Revoke the removed member's tokens when membership ends. */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    await revokeTokensForRemovedMember(
      payload.orgId,
      payload.userId,
      payload.actorId,
    );
  });
}

