import { hashToken, randomToken } from "@/lib/hash";
import { PermissionDeniedError, assertCan } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";
import type { PermissionAction } from "@/types/permission";

/** A user may hold this many usable tokens in one organization. */
const MAX_USABLE_TOKENS = 5;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Bytes of entropy after the `tfk_` prefix. Matches the session token width. */
const SECRET_BYTES = 32;

const SECRET_PREFIX = "tfk_";

/** Display prefix stored on the row: the first 12 characters of the secret. */
const PREFIX_LENGTH = 12;

/**
 * Role gate that throws the codebase's permission-denied error.
 *
 * `hasRoleAtLeast` is the check the product rule names (a viewer stays a
 * viewer even under the staff bypass). `assertCan` is what produces
 * `PermissionDeniedError` for an ordinary member.
 */
function assertRoleAtLeast(
  actor: Actor,
  atLeast: Role,
  action: PermissionAction,
  orgId: OrgId,
): void {
  if (hasRoleAtLeast(actor.role, atLeast)) return;
  assertCan(actor, action, orgResource(orgId));
  throw new PermissionDeniedError(action, {
    allowed: false,
    action,
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

