  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertRoleAtLeast(actor, "member", "project:create", parsed.orgId);
  }

  const created = new Date();
  const createdAt = toIsoTimestamp(created);
  const token = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiToken(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(created.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt,
    },
    MAX_USABLE_TOKENS,
  );

  if (!apiToken) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS} usable API tokens in an organization`,
    );
  }

  await emit("api_token.created", {
    orgId: apiToken.orgId,
    actorId: actor.userId,
    occurredAt: apiToken.createdAt,
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
  });

