    await apiTokenRepo.findById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (existing.userId !== actor.userId) {
    assertRoleAtLeast(actor, "admin", "org:update", orgId);
  }

  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.revokeToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );

