  // call must not append a second audit entry.
  if (!revoked) {
    return requireFound(
      await apiTokenRepo.findById(orgId, tokenId),
      "ApiToken",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    orgId,
    actorId: actor.userId,
    occurredAt: revoked.revokedAt ?? toIsoTimestamp(new Date()),
    tokenId: revoked.id,
    name: revoked.name,
  });

