  orgId: OrgId,
  userId: UserId,
  actorId: UserId | null,
): Promise<void> {
  const tokens = await apiTokenRepo.listForUser(orgId, userId);
  const now = toIsoTimestamp(new Date());

  for (const token of tokens) {
    if (token.revokedAt !== null) continue;

    const revoked = await apiTokenRepo.revokeToken(orgId, token.id, now);
    if (!revoked) continue;

    await emit("api_token.revoked", {
      orgId,
      actorId,
      occurredAt: revoked.revokedAt ?? now,
      tokenId: revoked.id,
      name: revoked.name,
    });
  }
