import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { ZodError } from "zod";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { apiTokens, getDb } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import {
  authenticateApiToken,
  createApiToken,
  listApiTokens,
  revokeApiToken,
} from "@/server/services/api-token-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as memberService from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { eq } from "drizzle-orm";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("tokens", "growth");
  other = await createTenant("tokens-other", "growth");
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

async function audits(action: "api_token.created" | "api_token.revoked", orgId = tenant.org.id) {
  const page = await activityRepo.listActivity({
    orgId,
    action: [action],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("api tokens", () => {
  it("creates, lists newest first, and audits without the secret", async () => {
    const first = await createApiToken(tenant.actors.viewer, {
      orgId: tenant.org.id,
      name: "  ci reader  ",
      scope: "read",
      expiresInDays: 7,
    });
    const second = await createApiToken(tenant.actors.viewer, {
      orgId: tenant.org.id,
      name: "second",
      scope: "read",
      expiresInDays: 1,
    });

    expect(first.token.startsWith("tfk_")).toBe(true);
    expect(first.token).toMatch(/^tfk_[A-Za-z0-9_-]+$/);
    expect(first.apiToken.prefix).toBe(first.token.slice(0, 12));
    expect(first.apiToken.name).toBe("ci reader");
    expect(first.apiToken.lastUsedAt).toBeNull();
    expect(first.apiToken.revokedAt).toBeNull();
    expect(first.apiToken.scope).toBe("read");

    const createdMs = new Date(first.apiToken.createdAt).getTime();
    const expiresMs = new Date(first.apiToken.expiresAt).getTime();
    expect(expiresMs - createdMs).toBe(7 * 24 * 60 * 60 * 1000);

    const listed = await listApiTokens(tenant.actors.viewer, tenant.org.id);
    expect(listed.map((token) => token.id)).toEqual([
      second.apiToken.id,
      first.apiToken.id,
    ]);

    const rows = getDb()
      .select()
      .from(apiTokens)
      .where(eq(apiTokens.id, first.apiToken.id))
      .all();
    expect(rows[0]?.tokenHash).toBe(hashToken(first.token));
    const dumped = JSON.stringify(rows);
    expect(dumped).not.toContain(first.token);
    expect(dumped).toContain(hashToken(first.token));

    const created = await audits("api_token.created");
    const mine = created.filter((row) => row.subjectId === first.apiToken.id);
    expect(mine).toHaveLength(1);
    expect(mine[0]).toMatchObject({
      action: "api_token.created",
      subjectKind: "api_token",
      actorId: tenant.userIds.viewer,
    });
    expect(JSON.stringify(mine)).not.toContain(first.token);
    expect(JSON.stringify(mine)).not.toContain(hashToken(first.token));
  });

  it("rejects invalid input with ZodError and stores nothing", async () => {
    const before = await listApiTokens(tenant.actors.owner, tenant.org.id);
    await expect(
      createApiToken(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "   ",
        scope: "read",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(ZodError);
    await expect(
      createApiToken(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "ok",
        scope: "write",
        expiresInDays: 1.5 as unknown as number,
      }),
    ).rejects.toBeInstanceOf(ZodError);
    const after = await listApiTokens(tenant.actors.owner, tenant.org.id);
    expect(after).toHaveLength(before.length);
  });

  it("enforces tenant scope, write role, and the usable cap", async () => {
    await expect(
      createApiToken(tenant.actors.member, {
        orgId: other.org.id,
        name: "cross",
        scope: "read",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      createApiToken(tenant.actors.viewer, {
        orgId: tenant.org.id,
        name: "nope",
        scope: "write",
        expiresInDays: 3,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const memberTokens = [];
    for (let i = 0; i < 5; i += 1) {
      memberTokens.push(
        await createApiToken(tenant.actors.member, {
          orgId: tenant.org.id,
          name: `m${i}`,
          scope: "write",
          expiresInDays: 10,
        }),
      );
    }
    await expect(
      createApiToken(tenant.actors.member, {
        orgId: tenant.org.id,
        name: "sixth",
        scope: "read",
        expiresInDays: 2,
      }),
    ).rejects.toThrow(/5/);

    const still = await listApiTokens(tenant.actors.member, tenant.org.id);
    expect(still).toHaveLength(5);

    await revokeApiToken(
      tenant.actors.member,
      tenant.org.id,
      memberTokens[0]!.apiToken.id,
    );
    const replacement = await createApiToken(tenant.actors.member, {
      orgId: tenant.org.id,
      name: "after revoke",
      scope: "read",
      expiresInDays: 2,
    });
    expect(replacement.apiToken.name).toBe("after revoke");

    const expired = memberTokens[1]!;
    getDb()
      .update(apiTokens)
      .set({ expiresAt: toIsoTimestamp(new Date(Date.now() - 1000)) })
      .where(eq(apiTokens.id, expired.apiToken.id))
      .run();
    const afterExpiry = await createApiToken(tenant.actors.member, {
      orgId: tenant.org.id,
      name: "after expiry",
      scope: "read",
      expiresInDays: 2,
    });
    expect(afterExpiry.apiToken.id).not.toBe(expired.apiToken.id);

    const ownerOwn = await createApiToken(tenant.actors.owner, {
      orgId: tenant.org.id,
      name: "owner",
      scope: "write",
      expiresInDays: 4,
