describe("api tokens", () => {
  it("creates, lists newest first, and audits without the secret", async () => {
    const first = await createApiToken(tenant.actors.viewer, {
      orgId: tenant.org.id,
      name: "  ci reader  ",
      scope: "read",
      expiresInDays: 7,
    });
    const second = await createApiToken(tenant.actors.viewer, {
      orgId: tenant.org.id,
      name: "second",
      scope: "read",
      expiresInDays: 1,
    });

    expect(first.token.startsWith("tfk_")).toBe(true);
    expect(first.token).toMatch(/^tfk_[A-Za-z0-9_-]+$/);
    expect(first.apiToken.prefix).toBe(first.token.slice(0, 12));
    expect(first.apiToken.name).toBe("ci reader");
    expect(first.apiToken.lastUsedAt).toBeNull();
    expect(first.apiToken.revokedAt).toBeNull();
    expect(first.apiToken.scope).toBe("read");

    const createdMs = new Date(first.apiToken.createdAt).getTime();
    const expiresMs = new Date(first.apiToken.expiresAt).getTime();
    expect(expiresMs - createdMs).toBe(7 * 24 * 60 * 60 * 1000);

    const listed = await listApiTokens(tenant.actors.viewer, tenant.org.id);
    expect(listed.map((token) => token.id)).toEqual([
      second.apiToken.id,
      first.apiToken.id,
    ]);

    const rows = getDb()
      .select()
      .from(apiTokens)
      .where(eq(apiTokens.id, first.apiToken.id))
      .all();
    expect(rows[0]?.tokenHash).toBe(hashToken(first.token));
    const dumped = JSON.stringify(rows);
    expect(dumped).not.toContain(first.token);
    expect(dumped).toContain(hashToken(first.token));

    const created = await audits("api_token.created");
    const mine = created.filter((row) => row.subjectId === first.apiToken.id);
    expect(mine).toHaveLength(1);
    expect(mine[0]).toMatchObject({
      action: "api_token.created",
      subjectKind: "api_token",
      actorId: tenant.userIds.viewer,
    });
    expect(JSON.stringify(mine)).not.toContain(first.token);
    expect(JSON.stringify(mine)).not.toContain(hashToken(first.token));
  });

  it("rejects invalid input with ZodError and stores nothing", async () => {
