      createApiToken(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "   ",
        scope: "read",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(ZodError);
    await expect(
      createApiToken(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "ok",
        scope: "write",
        expiresInDays: 1.5 as unknown as number,
      }),
    ).rejects.toBeInstanceOf(ZodError);
    const after = await listApiTokens(tenant.actors.owner, tenant.org.id);
    expect(after).toHaveLength(before.length);
  });

  it("enforces tenant scope, write role, and the usable cap", async () => {
    await expect(
      createApiToken(tenant.actors.member, {
        orgId: other.org.id,
        name: "cross",
        scope: "read",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      createApiToken(tenant.actors.viewer, {
        orgId: tenant.org.id,
        name: "nope",
        scope: "write",
        expiresInDays: 3,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const memberTokens = [];
    for (let i = 0; i < 5; i += 1) {
      memberTokens.push(
        await createApiToken(tenant.actors.member, {
          orgId: tenant.org.id,
          name: `m${i}`,
          scope: "write",
          expiresInDays: 10,
        }),
      );
    }
    await expect(
      createApiToken(tenant.actors.member, {
        orgId: tenant.org.id,
        name: "sixth",
        scope: "read",
        expiresInDays: 2,
      }),
    ).rejects.toThrow(/5/);

    const still = await listApiTokens(tenant.actors.member, tenant.org.id);
    expect(still).toHaveLength(5);

    await revokeApiToken(
      tenant.actors.member,
      tenant.org.id,
      memberTokens[0]!.apiToken.id,
    );
    const replacement = await createApiToken(tenant.actors.member, {
      orgId: tenant.org.id,
      name: "after revoke",
      scope: "read",
      expiresInDays: 2,
    });
    expect(replacement.apiToken.name).toBe("after revoke");

    const expired = memberTokens[1]!;
    getDb()
      .update(apiTokens)
      .set({ expiresAt: toIsoTimestamp(new Date(Date.now() - 1000)) })
      .where(eq(apiTokens.id, expired.apiToken.id))
      .run();
    const afterExpiry = await createApiToken(tenant.actors.member, {
      orgId: tenant.org.id,
      name: "after expiry",
      scope: "read",
      expiresInDays: 2,
    });
    expect(afterExpiry.apiToken.id).not.toBe(expired.apiToken.id);

    const ownerOwn = await createApiToken(tenant.actors.owner, {
      orgId: tenant.org.id,
