    getDb()
      .update(apiTokens)
      .set({ revokedAt: null, expiresAt: exact, lastUsedAt: beforeFail ?? null })
      .where(eq(apiTokens.id, read.apiToken.id))
      .run();
    const realNow = Date.now;
    const RealDate = Date;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (globalThis as any).Date = class extends RealDate {
      constructor(...args: ConstructorParameters<typeof RealDate>) {
        if (args.length === 0) {
          super(exact);
          return;
        }
        super(...args);
      }
      static now() {
        return new RealDate(exact).getTime();
      }
    };
    Date.now = () => new RealDate(exact).getTime();
    try {
      expect(await authenticateApiToken(read.token)).toBeNull();
    } finally {
      globalThis.Date = RealDate;
      Date.now = realNow;
    }
    const afterExact = (await listApiTokens(tenant.actors.owner, tenant.org.id)).find(
      (token) => token.id === read.apiToken.id,
